class Solution:

	def isMatch(self, s, p):
		i = 0
		j = 0
		star = -1
		lenp = len(p)
		while i < len(s):
			if j < lenp and (s[i] == p[j] or p[j] == '?'):
				i += 1
				j += 1
			elif j < lenp and p[j] == '*':
				star = j
				mi = i
				j += 1
			elif star != -1:
				mi += 1
				i = mi
				j = star + 1
			else:
				return False
		while j < lenp and p[j] == '*':
			j += 1
		return j == lenp
